1	//! The ribbon along the top of the main window: tabs, with the selected tab's
2	//! commands beneath them in labelled groups. Each tab is a module of its own,
3	//! which says which commands it holds, and renders and runs them.
4	//!
5	//! Following the usual ribbon conventions: main commands are large icons
6	//! above their labels, tooltips explain rather than repeat the label and give
7	//! any shortcut, a command that can't run is disabled rather than hidden,
8	//! groups are titled down their left edge, and the ribbon collapses by
9	//! double-clicking a tab, its chevron beside the project indicator, or
10	//! Ctrl/Cmd+F1, which is remembered
11	//! across launches. Collapsed, the tabs go too, and the
12	//! commands marked primary (for now, all of them) sit small in a single row.
13	
14	use gpui_kit::assets::IconName;
15	use gpui_kit::component::button::{Button, ButtonCustomVariant, ButtonRounded, ButtonVariants};
16	use gpui_kit::component::tab::{Tab, TabBar};
17	use gpui_kit::component::{
18	    ActiveTheme, Icon, Selectable as _, Sizable as _, Size, StyledExt as _, h_flex, v_flex,
19	};
20	use gpui_kit::prelude::FluentBuilder as _;
21	use gpui_kit::*;
22	
23	use crate::activity::{Job, RevealJob};
24	use crate::project_directory::ProjectDirectory;
25	use crate::project_indicator::ProjectIndicator;
26	
27	mod application_tab;
28	mod code_tab;
29	mod project_tab;
30	mod research_tab;
31	mod spec_tab;
32	
33	pub use application_tab::set_dark_mode;
34	
35	actions!(
36	    suspense,
37	    [
38	        ToggleRibbon,
39	        ShowTab1,
40	        ShowTab2,
41	        ShowTab3,
42	        ShowTab4,
43	        ShowTab5,
44	        RunPrimary,
45	        RunRelease
46	    ]
47	);
48	
49	/// The height of the row of tabs: gpui-kit's tab bar, less the line along its
50	/// bottom and a pixel more, so that at a fractional display scale, where the
51	/// clip falls between device pixels, no softened edge of that line shows as a
52	/// faint seam between the tabs and the commands beneath them.
53	const TAB_ROW_HEIGHT: Pixels = px(30.);
54	
55	/// How long the box a group's title is drawn across is before it is turned:
56	/// longer than any group is tall, so the title is centred in its strip
57	/// whatever the group's height, and clipped by the strip if a group is ever
58	/// shorter than its title is long.
59	const GROUP_TITLE_LENGTH: Pixels = px(240.);
60	
61	/// The padding at the right end of the commands, and above and below the buttons,
62	/// though not the groups' title strips, which run the body's full height; and
63	/// the gap between one command and the next, across and down.
64	const BODY_PADDING: Pixels = px(8.);
65	
66	/// A slim button's height.
67	const SLIM_HEIGHT: Pixels = px(22.);
68	
69	/// Slim buttons stacked in one column, at most.
70	const SLIM_STACK: usize = 2;
71	
72	/// How tall a column of `slim` slim buttons is, with the gaps between them.
73	fn stacked(slim: usize) -> Pixels {
74	    SLIM_HEIGHT * slim as f32 + BODY_PADDING * (slim as f32 - 1.)
75	}
76	
77	/// A full button is exactly two slim buttons tall, however much its icon and
78	/// label would take.
79	fn full_height() -> Pixels {
80	    stacked(SLIM_STACK)
81	}
82	
83	/// The width of the strip down a group's left edge that holds its title,
84	/// leaving room either side of the title.
85	const GROUP_TITLE_WIDTH: Pixels = px(28.);
86	
87	/// The size of a group's title.
88	const GROUP_TITLE_SIZE: f32 = 12.;
89	
90	/// Ctrl+F1 (Cmd+F1 on macOS) collapses or expands the ribbon, as in Office.
91	pub fn bind_keys(cx: &mut App) {
92	    cx.bind_keys([
93	        #[cfg(target_os = "macos")]
94	        KeyBinding::new("cmd-f1", ToggleRibbon, None),
95	        #[cfg(not(target_os = "macos"))]
96	        KeyBinding::new("ctrl-f1", ToggleRibbon, None),
97	        // Ctrl+F5 (Cmd+F5 on macOS) runs the project's primary run target.
98	        #[cfg(target_os = "macos")]
99	        KeyBinding::new("cmd-f5", RunPrimary, None),
100	        #[cfg(not(target_os = "macos"))]
101	        KeyBinding::new("ctrl-f5", RunPrimary, None),
102	        // With Shift, the release build.
103	        #[cfg(target_os = "macos")]
104	        KeyBinding::new("cmd-shift-f5", RunRelease, None),
105	        #[cfg(not(target_os = "macos"))]
106	        KeyBinding::new("ctrl-shift-f5", RunRelease, None),
107	        // Alt+1 to Alt+5 open the tabs in the order they are shown.
108	        KeyBinding::new("alt-1", ShowTab1, None),
109	        KeyBinding::new("alt-2", ShowTab2, None),
110	        KeyBinding::new("alt-3", ShowTab3, None),
111	        KeyBinding::new("alt-4", ShowTab4, None),
112	        KeyBinding::new("alt-5", ShowTab5, None),
113	    ]);
114	}
115	
116	/// A tab of the ribbon.
117	#[derive(Clone, Copy, Debug, PartialEq)]
118	pub enum RibbonTab {
119	    Project,
120	    Code,
121	    Spec,
122	    Research,
123	    Application,
124	}
125	
126	impl RibbonTab {
127	    /// Every tab, in order.
128	    pub const ALL: [RibbonTab; 5] = [
129	        RibbonTab::Project,
130	        RibbonTab::Code,
131	        RibbonTab::Spec,
132	        RibbonTab::Research,
133	        RibbonTab::Application,
134	    ];
135	
136	    fn label(self) -> &'static str {
137	        match self {
138	            RibbonTab::Project => "Project",
139	            RibbonTab::Code => "Code",
140	            RibbonTab::Spec => "Spec",
141	            RibbonTab::Research => "Research",
142	            RibbonTab::Application => "Application",
143	        }
144	    }
145	
146	    /// The chat input mode the tab works on, whose colour it takes while
147	    /// open: Code and Spec have one; the others don't.
148	    fn mode(self) -> Option<crate::chat_input::SendMode> {
149	        match self {
150	            RibbonTab::Code => Some(crate::chat_input::SendMode::Code),
151	            RibbonTab::Spec => Some(crate::chat_input::SendMode::Spec),
152	            RibbonTab::Project | RibbonTab::Research | RibbonTab::Application => None,
153	        }
154	    }
155	
156	    /// The tab's commands, in the order of its groups.
157	    fn commands(self, cx: &App) -> Vec<CommandPlace> {
158	        match self {
159	            RibbonTab::Project => project_tab::COMMANDS.to_vec(),
160	            RibbonTab::Code => code_tab::commands(cx),
161	            RibbonTab::Spec => spec_tab::COMMANDS.to_vec(),
162	            RibbonTab::Research => research_tab::COMMANDS.to_vec(),
163	            RibbonTab::Application => application_tab::COMMANDS.to_vec(),
164	        }
165	    }
166	}
167	
168	/// A command in the ribbon, from whichever tab holds it.
169	#[derive(Clone, Copy, Debug, PartialEq)]
170	enum Command {
171	    NewProject,
172	    OpenProject,
173	    BuildSpec,
174	    NewScope,
175	    NewConcept,
176	    NewShape,
177	    NewInstruction,
178	    AnalyzeDivergence,
179	    ViewDivergenceReports,
180	    GenerateSkills,
181	    Rescope,
182	    FindHowToRun,
183	    RunTarget(usize),
184	    FindRunAgain,
185	    DarkMode,
186	    Settings,
187	}
188	
189	/// Where a command sits in its tab, and whether it stays in the collapsed
190	/// ribbon.
191	#[derive(Clone, Copy)]
192	struct CommandPlace {
193	    command: Command,
194	    group: &'static str,
195	    /// Full or slim.
196	    size: CommandSize,
197	    /// Shown, small, in the collapsed ribbon.
198	    primary: bool,
199	}
200	
201	/// How a command's button is laid out.
202	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
203	enum CommandSize {
204	    /// The full height of the body, its icon large above its label.
205	    Full,
206	    /// Near enough half of that, its small icon left of its label; slim
207	    /// buttons side by side stack down, two to a column.
208	    Slim,
209	    /// As tall as slim but only as wide as its icon and label, for the
210	    /// collapsed ribbon's row.
211	    Small,
212	}
213	
214	pub struct Ribbon {
215	    /// The open tabs, in the order of the tabs; never empty. A click opens one
216	    /// alone, and Ctrl/Cmd+click opens or closes one alongside the others.
217	    open_tabs: Vec<RibbonTab>,
218	    /// Collapsed to a row of its primary commands; the choice is kept across
219	    /// launches.
220	    collapsed: bool,
221	    /// The projects a spec build runs in, on its own.
222	    building: Vec<std::path::PathBuf>,
223	    /// Everything running, shown as a spinner beside the project's name.
224	    jobs: Vec<Job>,
225	    /// Whether the list of what's running is open.
226	    jobs_open: bool,
227	    /// Which project is open, and the recent projects when clicked.
228	    project_indicator: Entity<ProjectIndicator>,
229	}
230	
231	impl EventEmitter<RevealJob> for Ribbon {}
232	impl EventEmitter<RunCommand> for Ribbon {}
233	
234	/// Emitted by the Code tab's run commands.
235	#[derive(Clone, Copy, Debug, PartialEq)]
236	pub enum RunCommand {
237	    /// Find how the project is run.
238	    Find,
239	    /// Run the project's target at this index.
240	    Target(usize),
241	}
242	
243	impl Ribbon {
244	    pub fn new(cx: &mut Context<Self>) -> Self {
245	        cx.observe_global::<ProjectDirectory>(|_, cx| cx.notify())
246	            .detach();
247	        cx.observe_global::<crate::run_targets::ProjectTargets>(|_, cx| cx.notify())
248	            .detach();
249	        Self {
250	            // Always Project at launch: which tab was last open isn't kept.
251	            open_tabs: vec![RibbonTab::Project],
252	            collapsed: collapsed_preference::load(),
253	            building: Vec::new(),
254	            jobs: Vec::new(),
255	            jobs_open: false,
256	            project_indicator: cx.new(ProjectIndicator::new),
257	        }
258	    }
259	
260	    /// Everything running, as the spinner and its list show it. The list
261	    /// closes once nothing is.
262	    pub fn set_jobs(&mut self, jobs: Vec<Job>, cx: &mut Context<Self>) {
263	        if self.jobs == jobs {
264	            return;
265	        }
266	        self.jobs = jobs;
267	        if self.jobs.is_empty() {
268	            self.jobs_open = false;
269	        }
270	        cx.notify();
271	    }
272	
273	    #[cfg(test)]
274	    pub fn jobs(&self) -> &[Job] {
275	        &self.jobs
276	    }
277	
278	    /// The project indicator.
279	    pub fn project_indicator(&self) -> &Entity<ProjectIndicator> {
280	        &self.project_indicator
281	    }
282	
283	    pub fn jobs_open(&self) -> bool {
284	        self.jobs_open
285	    }
286	
287	    pub fn close_jobs(&mut self, cx: &mut Context<Self>) {
288	        if self.jobs_open {
289	            self.jobs_open = false;
290	            cx.notify();
291	        }
292	    }
293	
294	    /// The project indicator, a solid block the full height of the row, with
295	    /// no line between it and what follows. Lets UI tests find it; inert in
296	    /// normal builds.
297	    fn render_indicator(&self) -> impl IntoElement {
298	        gpui_kit::TestSupportExt::test_support(
299	            div()
300	                .id("ribbon-prefix")
301	                .flex()
302	                .flex_none()
303	                .h_full()
304	                .child(self.project_indicator.clone()),
305	        )
306	    }
307	
308	    /// The left container: the project indicator, the collapse chevron, and
309	    /// the activity spinner while anything is running, leading the bar
310	    /// whether expanded or collapsed.
311	    fn render_left(&self, collapse: Button, cx: &mut Context<Self>) -> Option<AnyElement> {
312	        let items = [
313	            Some(self.render_indicator().into_any_element()),
314	            Some(collapse.into_any_element()),
315	            self.render_activity(cx),
316	        ];
317	        container("ribbon-left", items.into_iter().flatten().collect())
318	    }
319	
320	    /// The right container, ending the bar; it holds nothing yet.
321	    fn render_right(&self) -> Option<AnyElement> {
322	        container("ribbon-right", Vec::new())
323	    }
324	
325	    /// The spinner beside the project's name while anything is running, with
326	    /// how many things are when more than one is; clicking it opens the list
327	    /// of them, and clicking one reveals it.
328	    fn render_activity(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
329	        if self.jobs.is_empty() {
330	            return None;
331	        }
332	        let theme = cx.theme();
333	        let count = self.jobs.len();
334	        let tooltip: SharedString = if count == 1 {
335	            let job = &self.jobs[0];
336	            match &job.detail {
337	                Some(detail) => format!("{}: {detail}", job.title).into(),
338	                None => job.title.clone(),
339	            }
340	        } else {
341	            format!("{count} things running").into()
342	        };
343	        let list = self.jobs_open.then(|| {
344	            let rows = self.jobs.iter().enumerate().map(|(ix, job)| {
345	                let (kind, project) = (job.kind, job.project.clone());
346	                let row = h_flex()
347	                    .id(("ribbon-job", ix))
348	                    .gap_2()
349	                    .px_3()
350	                    .py_1p5()
351	                    .rounded(theme.radius)
352	                    .cursor_pointer()
353	                    .hover(|row| row.bg(theme.list_hover))
354	                    .on_click(cx.listener(move |this, _, _, cx| {
355	                        this.jobs_open = false;
356	                        cx.emit(RevealJob(kind, project.clone()));
357	                        cx.notify();
358	                    }))
359	                    .child(gpui_kit::component::spinner::Spinner::new().small())
360	                    .child(div().flex_none().font_medium().child(job.title.clone()))
361	                    .children(job.detail.clone().map(|detail| {
362	                        div()
363	                            .flex_1()
364	                            .min_w_0()
365	                            .truncate()
366	                            .text_color(theme.muted_foreground)
367	                            .child(detail)
368	                    }));
369	                // Lets UI tests find the row; inert in normal builds.
370	                gpui_kit::TestSupportExt::test_support(row)
371	            });
372	            let list = v_flex()
373	                .id("ribbon-jobs")
374	                .w(px(360.))
375	                .mt(px(28.))
376	                .p_1()
377	                .rounded(theme.radius)
378	                .border_1()
379	                .border_color(theme.border)
380	                .bg(theme.popover)
381	                .shadow_md()
382	                .occlude()
383	                .on_mouse_down_out(cx.listener(|this, _, _, cx| this.close_jobs(cx)))
384	                .children(rows);
385	            // Lets UI tests find the list; inert in normal builds.
386	            deferred(
387	                anchored()
388	                    .snap_to_window()
389	                    .child(gpui_kit::TestSupportExt::test_support(list)),
390	            )
391	            .with_priority(2)
392	        });
393	        let spinner = h_flex()
394	            .id("ribbon-activity")
395	            .flex_none()
396	            .gap_1()
397	            .px_1()
398	            .py_0p5()
399	            .rounded(theme.radius)
400	            .cursor_pointer()
401	            .hover(|spinner| spinner.bg(theme.list_hover))
402	            .tooltip(move |window, cx| {
403	                gpui_kit::component::tooltip::Tooltip::new(tooltip.clone()).build(window, cx)
404	            })
405	            .on_click(cx.listener(|this, _, _, cx| {
406	                this.jobs_open = !this.jobs_open;
407	                cx.notify();
408	            }))
409	            .child(gpui_kit::component::spinner::Spinner::new().small())
410	            .when(count > 1, |spinner| {
411	                spinner.child(
412	                    div()
413	                        .text_xs()
414	                        .text_color(theme.muted_foreground)
415	                        .child(count.to_string()),
416	                )
417	            })
418	            .children(list);
419	        // Lets UI tests find the spinner; inert in normal builds.
420	        Some(gpui_kit::TestSupportExt::test_support(spinner).into_any_element())
421	    }
422	
423	    /// Whether the ribbon is collapsed to its primary commands.
424	    #[cfg(test)]
425	    pub fn is_collapsed(&self) -> bool {
426	        self.collapsed
427	    }
428	
429	    /// Collapses the ribbon to its primary commands, or expands it again,
430	    /// remembering the choice.
431	    pub fn toggle_collapsed(&mut self, cx: &mut Context<Self>) {
432	        self.collapsed = !self.collapsed;
433	        collapsed_preference::save(self.collapsed);
434	        cx.notify();
435	    }
436	
437	    /// A tab was clicked: it opens alone, and a double-click collapses the
438	    /// ribbon; with `add`, from Ctrl/Cmd+click, it opens alongside the others,
439	    /// or closes if it was open, unless it is the only one. (Collapsed, there
440	    /// are no tabs to click.)
441	    pub(crate) fn tab_clicked(
442	        &mut self,
443	        tab: RibbonTab,
444	        clicks: usize,
445	        add: bool,
446	        cx: &mut Context<Self>,
447	    ) {
448	        if add {
449	            self.open_tabs = toggle_open(&self.open_tabs, tab);
450	        } else {
451	            self.open_tabs = vec![tab];
452	            if clicks >= 2 && !self.collapsed {
453	                self.toggle_collapsed(cx);
454	            }
455	        }
456	        cx.notify();
457	    }
458	
459	    /// Opens the tab at `ix`, counting from 0 in the order the tabs are shown,
460	    /// alone, as a click does, expanding the ribbon if it is collapsed. An
461	    /// index past the last tab does nothing.
462	    pub fn show_tab_at(&mut self, ix: usize, cx: &mut Context<Self>) {
463	        let Some(&tab) = RibbonTab::ALL.get(ix) else {
464	            return;
465	        };
466	        if self.collapsed {
467	            self.toggle_collapsed(cx);
468	        }
469	        self.select_tab(tab, cx);
470	    }
471	
472	    /// Opens `tab` alone.
473	    pub fn select_tab(&mut self, tab: RibbonTab, cx: &mut Context<Self>) {
474	        self.open_tabs = vec![tab];
475	        cx.notify();
476	    }
477	
478	    #[cfg(test)]
479	    pub fn open_tabs(&self) -> &[RibbonTab] {
480	        &self.open_tabs
481	    }
482	}
483	
484	impl Ribbon {
485	    /// `command`'s control: large, with its icon above its label, or small,
486	    /// with its icon beside it, for the collapsed ribbon.
487	    fn render_command(
488	        &self,
489	        command: Command,
490	        size: CommandSize,
491	        cx: &mut Context<Self>,
492	    ) -> AnyElement {
493	        let colors = command_colors(cx);
494	        let rest = command_shades(cx).0;
495	        let button_with = |id: ElementId, icon: IconName, label: SharedString| {
496	            // gpui-kit keeps only a fifth of a custom button's resting colour,
497	            // so the colour is given to the button itself; its hover and
498	            // pressed colours are taken whole.
499	            let button = Button::new(id)
500	                .custom(colors)
501	                .rounded(ButtonRounded::None)
502	                .bg(rest);
503	            match size {
504	                // Slim fills its column; small, in a row, never stretches.
505	                CommandSize::Slim | CommandSize::Small => button
506	                    .small()
507	                    .h(SLIM_HEIGHT)
508	                    .map(|button| match size {
509	                        CommandSize::Small => button.flex_none(),
510	                        _ => button.w_full(),
511	                    })
512	                    .px_2()
513	                    .icon(Icon::new(icon).with_size(Size::Small))
514	                    .label(label),
515	                // As tall as its own icon and label need, rather than the
516	                // height a button takes by default.
517	                CommandSize::Full => button.flex_none().h_auto().px_3().py_1p5().child(
518	                    v_flex()
519	                        .items_center()
520	                        .gap_1()
521	                        .child(Icon::new(icon).with_size(Size::Large))
522	                        .child(div().text_xs().child(label)),
523	                ),
524	            }
525	        };
526	        let button = |id: &'static str, icon: IconName, label: SharedString| {
527	            button_with(id.into(), icon, label)
528	        };
529	        match command {
530	            Command::FindHowToRun => code_tab::find_how_to_run(&button_with, cx),
531	            Command::FindRunAgain => code_tab::find_again(&button_with, cx),
532	            Command::RunTarget(ix) => code_tab::run_target(ix, &button_with, cx),
533	            Command::NewProject => project_tab::new_project(button),
534	            Command::OpenProject => project_tab::open_project(button),
535	            Command::BuildSpec => spec_tab::build_spec(self, button, cx),
536	            Command::NewScope => spec_tab::new_scope(button, cx),
537	            Command::NewConcept => spec_tab::new_concept(button, cx),
538	            Command::NewShape => spec_tab::new_shape(button, cx),
539	            Command::NewInstruction => spec_tab::new_instruction(button, cx),
