550	/// A container at either end of the bar: what it holds side by side,
551	/// vertically centred, with no gap between them or padding around them,
552	/// only as wide as they are; nothing at all while it holds nothing. Lets UI
553	/// tests find it; inert in normal builds.
554	/// The collapse chevron's width and height.
555	const CHEVRON_SIZE: Pixels = px(22.);
556	
557	/// How tall the containers, and the row the collapsed ribbon becomes, are:
558	/// the tab row down to the line along its bottom, so the containers end on
559	/// that line and are the same height, their contents in the same place,
560	/// whether the ribbon is expanded or collapsed.
561	const ABOVE_LINE_HEIGHT: Pixels = px(29.);
562	
563	fn container(id: &'static str, items: Vec<AnyElement>) -> Option<AnyElement> {
564	    (!items.is_empty()).then(|| {
565	        gpui_kit::TestSupportExt::test_support(h_flex().id(id))
566	            .flex_none()
567	            .h(ABOVE_LINE_HEIGHT)
568	            .items_center()
569	            .children(items)
570	            .into_any_element()
571	    })
572	}
