574	impl Render for Ribbon {
575	    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
576	        let theme = cx.theme();
577	        let (border, muted) = (theme.border, theme.muted_foreground);
578	        let (title_background, font) = (theme.muted, theme.font_family.clone());
579	
580	        // Square, and the same size expanded or collapsed: only the way it
581	        // points changes.
582	        let collapse = Button::new("ribbon-collapse")
583	            .ghost()
584	            .xsmall()
585	            .flex_none()
586	            .size(CHEVRON_SIZE)
587	            .icon(if self.collapsed {
588	                IconName::ChevronDown
589	            } else {
590	                IconName::ChevronUp
591	            })
592	            .tooltip_with_action(
593	                if self.collapsed {
594	                    "Expand the ribbon"
595	                } else {
596	                    "Collapse the ribbon to its primary commands"
597	                },
598	                &ToggleRibbon,
599	                None,
600	            )
601	            .on_click(cx.listener(|this, _, _, cx| this.toggle_collapsed(cx)));
602	        let ribbon = div()
603	            .id("ribbon")
604	            .flex()
605	            .flex_col()
606	            .border_b_1()
607	            .border_color(border);
608	
609	        if self.collapsed {
610	            // No tabs: every primary command, small, in one row, a divider
611	            // between one tab's commands and the next, led by the project's
612	            // name, as beside the tabs.
613	            let mut row = Vec::new();
614	            let mut last_tab = None;
615	            let primary: Vec<_> = RibbonTab::ALL
616	                .into_iter()
617	                .flat_map(|tab| {
618	                    tab.commands(cx)
619	                        .into_iter()
620	                        .filter(|place| place.primary)
621	                        .map(move |place| (tab, place))
622	                })
623	                .collect();
624	            for (tab, place) in primary {
625	                if last_tab.is_some_and(|last| last != tab) {
626	                    // Centred like the controls, rather than stretched.
627	                    row.push(
628	                        div()
629	                            .flex_none()
630	                            .w_px()
631	                            .h(px(16.))
632	                            .bg(border)
633	                            .into_any_element(),
634	                    );
635	                }
636	                last_tab = Some(tab);
637	                row.push(self.render_command(place.command, CommandSize::Small, cx));
638	            }
639	            // Lets UI tests find the row; inert in normal builds. The
640	            // indicator and the chevron after it stay put; what follows them
641	            // scrolls sideways when it's wider than the room left.
642	            return ribbon.child(gpui_kit::TestSupportExt::test_support(
643	                h_flex()
644	                    .id("ribbon-primary")
645	                    // As tall as the tab row, down to the ribbon's bottom line
646	                    // as the tab row is to its own, so collapsing moves nothing.
647	                    .h(ABOVE_LINE_HEIGHT)
648	                    .items_stretch()
649	                    .children(self.render_left(collapse, cx))
650	                    .child(gpui_kit::TestSupportExt::test_support(
651	                        h_flex()
652	                            .id("ribbon-primary-commands")
653	                            .flex_1()
654	                            .min_w_0()
655	                            .overflow_x_scroll()
656	                            // Every control is vertically centred in the row.
657	                            .items_center()
658	                            .gap_2()
659	                            .px_2()
660	                            .children(row),
661	                    ))
662	                    .children(self.render_right()),
663	            ));
664	        }
665	
666	        // Each tab handles its own clicks, so a double-click can be told
667	        // apart: it collapses the ribbon. The tabs are gpui-kit's own, with
668	        // their default borders and spacing, in the theme's colours.
669	        let tabs = RibbonTab::ALL.map(|tab| {
670	            let open = self.open_tabs.contains(&tab);
671	            let tint = tab
672	                .mode()
673	                .map(|mode| crate::chat_input::mode_tint(mode, cx));
674	            let tab_ui = match tint {
675	                // A tab with a mode's colour shows it in its label while closed,
676	                // the hue at full strength; open, its label is the tab's own
677	                // colour. The label is the same text in the same place either
678	                // way, only its colour changing, so it never moves.
679	                Some(tint) => Tab::new().aria_label(tab.label()).child(
680	                    div()
681	                        .when(!open, |label| label.text_color(Hsla { a: 1., ..tint }))
682	                        .child(tab.label()),
683	                ),
684	                None => Tab::new().label(tab.label()),
685	            };
686	            tab_ui
687	                // An open Code or Spec tab is tinted as the chat input's tab of
688	                // that mode is: the tint laid over it, taking no room, so the
689	                // tab keeps its own size and its label stays put.
690	                .when_some(tint.filter(|_| open), |this, tint| {
691	                    this.child(div().absolute().inset_0().bg(tint))
692	                })
693	                .selected(open)
694	                .on_click(cx.listener(move |this, event: &ClickEvent, _, cx| {
695	                    this.tab_clicked(tab, event.click_count(), event.modifiers().secondary(), cx)
696	                }))
697	        });
698	        // The left container, holding the open project's name, the chevron,
699	        // and the activity spinner, left of the tab bar, and the right
700	        // container after it. gpui-kit's tab
701	        // bar draws a line along its bottom, which the tabs have none of here:
702	        // the row is a pixel shorter than the bar, clipping that line away and
703	        // leaving the tabs as they are.
704	        //
705	        // In its place, a line of the tabs' own border colour runs along the
706	        // bottom of the row, across the indicator and the whole bar. It is
707	        // drawn beneath the tabs, over a bar with no background of its own, so
708	        // each open tab's background covers it: the line runs from the far
709	        // left to an open tab's side border, and on from its other side
710	        // border to the far right, and the open tab meets the commands
711	        // beneath it with no line between them.
712	        let tab_bar = h_flex()
713	            .relative()
714	            .w_full()
715	            .h(TAB_ROW_HEIGHT)
716	            .overflow_hidden()
717	            .items_start()
718	            .bg(cx.theme().tab_bar)
719	            .children(self.render_left(collapse, cx))
720	            .child(gpui_kit::TestSupportExt::test_support(
721	                div()
722	                    .id("ribbon-tabs-line")
723	                    .absolute()
724	                    .left_0()
725	                    .right_0()
726	                    .bottom_0()
727	                    .h(px(1.))
728	                    .bg(border),
729	            ))
730	            .child(
731	                TabBar::new("ribbon-tabs")
732	                    .flex_1()
733	                    .bg(cx.theme().transparent)
734	                    .children(tabs),
735	            )
736	            .children(self.render_right());
737	
738	        // With a Code or Spec tab open alone, the body is tinted as the chat
739	        // input's is for that mode.
740	        let body_tint = match self.open_tabs.as_slice() {
741	            [tab] => tab
742	                .mode()
743	                .map(|mode| crate::chat_input::mode_tint(mode, cx)),
744	            _ => None,
745	        };
746	
747	        // Each open tab's commands, gathered into their groups in order.
748	        let mut row = Vec::new();
749	        for tab in &self.open_tabs {
750	            let mut groups: Vec<(&'static str, Vec<(CommandSize, AnyElement)>)> = Vec::new();
751	            for place in tab.commands(cx) {
752	                let element = (
753	                    place.size,
754	                    self.render_command(place.command, place.size, cx),
755	                );
756	                match groups.last_mut() {
757	                    Some((group, commands)) if *group == place.group => commands.push(element),
758	                    _ => groups.push((place.group, vec![element])),
759	                }
760	            }
761	            if groups.is_empty() {
762	                continue;
763	            }
764	            // No dividers, within a tab or between tabs: each group's title
765	            // strip marks where it starts.
766	            for (label, commands) in groups {
767	                row.push(group(label, commands, muted, title_background, &font));
768	            }
769	        }
770	        if row.is_empty() {
771	            row.push(
772	                div()
773	                    .flex()
774	                    .items_center()
775	                    .text_sm()
776	                    .pl(BODY_PADDING)
777	                    .py(BODY_PADDING)
778	                    .text_color(muted)
779	                    .child("No commands yet")
780	                    .into_any_element(),
781	            );
782	        }
783	
784	        // Lets UI tests find the tabs and the commands; inert in normal builds.
785	        let tab_bar =
786	            gpui_kit::TestSupportExt::test_support(div().id("ribbon-tabs-row").child(tab_bar));
787	        ribbon
788	            .child(tab_bar)
789	            .child(gpui_kit::TestSupportExt::test_support(
790	                div()
791	                    .id("ribbon-controls")
792	                    .flex()
793	                    .flex_row()
794	                    // Scrolls sideways when the open tabs' groups are wider
795	                    // than the window.
796	                    .overflow_x_scroll()
797	                    .items_stretch()
798	                    // Padding at the right only, so the first group's title
799	                    // strip starts at the body's left edge; the buttons are
800	                    // padded above and below within their groups, so the
801	                    // groups' title strips run the body's full height.
802	                    .pr(BODY_PADDING)
803	                    .gap(BODY_PADDING)
804	                    // No taller than its commands need.
805	                    .flex_none()
806	                    // With the Code tab open alone, its body is tinted as the
807	                    // chat input's body is for its mode.
808	                    .when_some(body_tint, |this, tint| {
809	                        this.bg(cx.theme().background.blend(tint))
810	                    })
811	                    .children(row),
812	            ))
813	    }
814	}
