816	/// The open tabs once `tab` is Ctrl/Cmd+clicked: opened alongside `open`, or
817	/// closed if it was open and isn't the only one; always in the order of the
818	/// tabs.
819	pub fn toggle_open(open: &[RibbonTab], tab: RibbonTab) -> Vec<RibbonTab> {
820	    let was_open = open.contains(&tab);
821	    if was_open && open.len() == 1 {
822	        return open.to_vec();
823	    }
824	    RibbonTab::ALL
825	        .into_iter()
826	        .filter(|candidate| {
827	            if *candidate == tab {
828	                !was_open
829	            } else {
830	                open.contains(candidate)
831	            }
832	        })
833	        .collect()
834	}
