836	/// A group of related commands, titled along its left edge, reading bottom to
837	/// top, on a strip of its own.
838	fn group(
839	    label: &'static str,
840	    commands: Vec<(CommandSize, AnyElement)>,
841	    muted: Hsla,
842	    title_background: Hsla,
843	    font: &str,
844	) -> AnyElement {
845	    // Full buttons stand alone; slim ones side by side stack down, two to a
846	    // column, top aligned.
847	    let mut columns: Vec<AnyElement> = Vec::new();
848	    let mut stack: Vec<AnyElement> = Vec::new();
849	    let flush = |stack: &mut Vec<AnyElement>, columns: &mut Vec<AnyElement>| {
850	        if !stack.is_empty() {
851	            columns.push(
852	                v_flex()
853	                    .flex_none()
854	                    .gap(BODY_PADDING)
855	                    .children(stack.drain(..))
856	                    .into_any_element(),
857	            );
858	        }
859	    };
860	    for (size, element) in commands {
861	        match size {
862	            CommandSize::Full => {
863	                flush(&mut stack, &mut columns);
864	                // Exactly two slim buttons tall, whatever its content; the
865	                // button itself fills that.
866	                columns.push(
867	                    h_flex()
868	                        .flex_none()
869	                        .items_stretch()
870	                        .overflow_hidden()
871	                        .h(full_height())
872	                        .child(element)
873	                        .into_any_element(),
874	                );
875	            }
876	            CommandSize::Slim | CommandSize::Small => {
877	                if stack.len() == SLIM_STACK {
878	                    flush(&mut stack, &mut columns);
879	                }
880	                stack.push(element);
881	            }
882	        }
883	    }
884	    flush(&mut stack, &mut columns);
885	    // Lets UI tests find the group; inert in normal builds.
886	    gpui_kit::TestSupportExt::test_support(h_flex().id(label))
887	        .items_stretch()
888	        .gap(BODY_PADDING)
889	        .child(
890	            div()
891	                .relative()
892	                .flex()
893	                .flex_none()
894	                .items_center()
895	                .overflow_hidden()
896	                .w(GROUP_TITLE_WIDTH)
897	                .bg(title_background)
898	                .child(group_title(label, muted, font)),
899	        )
900	        .child(
901	            // Each command takes the height it needs, a full button two slim
902	            // buttons.
903	            h_flex()
904	                .items_stretch()
905	                .py(BODY_PADDING)
906	                .gap(BODY_PADDING)
907	                .children(columns),
908	        )
909	        .into_any_element()
910	}
