912	/// A ribbon command's background at rest, hovered, and pressed.
913	fn command_shades(cx: &App) -> (Hsla, Hsla, Hsla) {
914	    let (white, black) = (hsla(0., 0., 1., 1.), hsla(0., 0., 0., 1.));
915	    if cx.theme().is_dark() {
916	        (white.opacity(0.14), white.opacity(0.22), black.opacity(0.2))
917	    } else {
918	        (white.opacity(0.45), white.opacity(0.7), black.opacity(0.12))
919	    }
920	}
