922	/// The colours of a ribbon command: its background laid over the body rather
923	/// than a colour of its own, so it contrasts a little with the body whatever
924	/// tint the body has, more while hovered, and more again while pressed.
925	fn command_colors(cx: &App) -> ButtonCustomVariant {
926	    let theme = cx.theme();
927	    let (rest, hover, active) = command_shades(cx);
928	    ButtonCustomVariant::new(cx)
929	        .color(rest)
930	        .hover(hover)
931	        .active(active)
932	        .foreground(theme.foreground)
933	}
