935	/// A group's title, turned -90deg. gpui can only turn an SVG, so the title is
936	/// drawn as SVG text: laid out across a long box, centred in it, then turned
937	/// about its own centre. The box is centred in the strip, so the title is
938	/// centred whatever the group's height.
939	fn group_title(label: &str, color: Hsla, font: &str) -> impl IntoElement {
940	    let (long, short) = (GROUP_TITLE_LENGTH, GROUP_TITLE_WIDTH);
941	    let escape = |text: &str| {
942	        text.replace('&', "&amp;")
943	            .replace('<', "&lt;")
944	            .replace('>', "&gt;")
945	            .replace('"', "&quot;")
946	    };
947	    let source = format!(
948	        r#"<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><text x="{x}" y="{y}" font-family="{font}" font-size="{GROUP_TITLE_SIZE}" text-anchor="middle" dominant-baseline="central" fill="black">{label}</text></svg>"#,
949	        w = f32::from(long),
950	        h = f32::from(short),
951	        x = f32::from(long) / 2.,
952	        y = f32::from(short) / 2.,
953	        // The SVG renderer doesn't know gpui's own names, like
954	        // ".SystemUIFont", so those take the usual sans serif.
955	        font = if font.starts_with('.') {
956	            "sans-serif".to_string()
957	        } else {
958	            format!("'{}', sans-serif", escape(font))
959	        },
960	        label = escape(label),
961	    );
962	    svg()
963	        .data(source.as_bytes())
964	        .flex_none()
965	        .ml((short - long) / 2.)
966	        .w(long)
967	        .h(short)
968	        .text_color(color)
969	        .with_transformation(Transformation::rotate(radians(
970	            -std::f32::consts::FRAC_PI_2,
971	        )))
972	}
