2038	                let project_tab = quads.iter().find(|quad| {
2039	                    quad.bounds.origin.x.0 >= chevron_right - 1.
2040	                        && quad.bounds.origin.x.0 - chevron_right < 8. * scale
2041	                        && (quad.bounds.origin.y.0 - top).abs() < 4.
2042	                        && quad.bounds.size.width.0 > 40. * scale
2043	                        && quad.background.as_solid() == Some(theme.tab_active)
