2062	                                && q.bounds.origin.y.0 + q.bounds.size.height.0 > line_y
2063	                                && m.origin.x.0 <= x
2064	                                && m.origin.x.0 + m.size.width.0 > x
2065	                                && m.origin.y.0 <= line_y
2066	                                && m.origin.y.0 + m.size.height.0 > line_y
