2095	                let bottom_line = quads.iter().find(|quad| {
2096	                    let bottom = quad.bounds.origin.y.0 + quad.bounds.size.height.0;
2097	                    let width = quad.border_widths.bottom.0;
2098	                    let mask = &quad.content_mask.bounds;
2099	                    width > 0.
2100	                        && quad.border_color.a > 0.
2101	                        && quad.bounds.origin.y.0 < 4.
2102	                        && quad.bounds.size.width.0 > 1000.
2103	                        && quad.bounds.size.height.0 < 80. * scale / 2.
2104	                        // At least a whole device pixel below what shows,
