2106	                        && bottom - width < mask.origin.y.0 + mask.size.height.0 + 1.
2107	                });
2108	                assert!(
2109	                    bottom_line.is_none(),
2110	                    "{mode:?}: a line runs along the bottom of the tabs: {bottom_line:?}"
2111	                );
2112	            })
2113	            .unwrap();
2114	        }
