    fn gpui_kit_follows_the_palette(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            super::init(cx);
            for (mode, p) in [(ThemeMode::Dark, DARK), (ThemeMode::Light, LIGHT)] {
                Theme::change(mode, None, cx);
                let theme = Theme::global(cx);
